    else:
        ctx.emit("missed", target=t, reach=1, by=me.id, weapon=wname, attack=attack, defence=defence)
    if me.state.braced:
        ctx.patch(me, {"braced": False})
    ctx.log(("hit for " + str(dmg) if hit else "miss") + " (" + str(attack) + " vs " + str(defence) + ")")
