def bonus(who, skill):
    # stat + skill rank, less the conditions everyone can see
    st = who.state
    skills = st.skills or {}
    b = int(st.get(stat_for(skill)) or 0) + int(skills.get(skill) or 0)
    if st.wounded:
        b = b - 2
    if st.thirsty:
        b = b - 2
